import * as fs from 'node:fs/promises';
import * as path from 'node:path';
import { gunzipSync } from 'node:zlib';
import { createHash } from 'node:crypto';
import { isDeepStrictEqual } from 'node:util';
import { pathToFileURL } from 'node:url';
import { spawnSync } from 'node:child_process';

for (const name of ['OCBI_PROJECT', 'OCBI_STUDY_ROOT', 'OCBI_PUBLICATION_PROJECT']) {
  if (!process.env[name]) throw new Error(`Missing required ${name}`);
}
const project = await fs.realpath(process.env.OCBI_PROJECT);
const work = await fs.realpath(process.env.OCBI_STUDY_ROOT);
const publication = await fs.realpath(process.env.OCBI_PUBLICATION_PROJECT);
if (project !== path.join(work, 'frozen-project-runtime') || publication === work || publication === project || publication.startsWith(project + path.sep)) throw new Error('Require distinct owned workspace, immutable engine and publication repository');
const directory = await fs.realpath(path.join(publication, 'benchmarks/results/self-curated-round3-2026-10-07'));
if (!directory.startsWith(publication + path.sep)) throw new Error('Publication directory escapes repository');
const digest = bytes => createHash('sha256').update(bytes).digest('hex');
function equal(actual, expected, label) {
  if (!isDeepStrictEqual(actual, expected)) throw new Error(`${label} mismatch`);
}
const packedBytes = await fs.readFile(path.join(directory, 'results-evidence.json.gz'));
const packed = JSON.parse(gunzipSync(packedBytes));
const preregBytes = await fs.readFile(path.join(directory, 'preregistration.json.gz'));
const prereg = JSON.parse(gunzipSync(preregBytes));
const reportBytes = await fs.readFile(path.join(directory, 'report.json'));
const published = JSON.parse(reportBytes);
equal(digest(reportBytes), packed.reportSha256, 'Public report hash');
for (const evidence of [packed, published]) equal(evidence.preregistrationArchiveSha256, digest(preregBytes), 'Preregistration archive binding');
const replay = await fs.mkdtemp(path.join(work, 'publication-replay-'));
const restore = text => text.replaceAll('${WORK}', replay).replaceAll('${PROJECT}', project).replaceAll('${REPO}', publication).replaceAll('${USER_HOME}', path.join(replay, 'home')).replaceAll('${DEVELOPMENT_ROOT}', process.env.OCBI_DEVELOPMENT_ROOT ?? path.join(replay, 'development-root'));
const files = new Map();
function safeTarget(base, relative) {
  if (path.isAbsolute(relative) || relative.includes('\\') || relative.split('/').some(part => part === '..' || part === '.' || !part)) throw new Error(`Unsafe evidence path: ${relative}`);
  const target = path.join(base, relative);
  if (!target.startsWith(base + path.sep)) throw new Error(`Evidence path escapes workspace: ${relative}`);
  return target;
}
for (const [kind, entries] of [['preregistration', prereg.files], ['results', packed.files]]) {
  const seen = new Set();
  for (const file of entries) {
    safeTarget(replay, file.path);
    if (seen.has(file.path)) throw new Error(`Duplicate ${kind} path: ${file.path}`);
    seen.add(file.path);
    equal(digest(Buffer.from(file.content)), file.normalizedSha256, `Embedded hash ${file.path}`);
    const original = await fs.realpath(safeTarget(work, file.path));
    if (!original.startsWith(work + path.sep)) throw new Error(`Original file escapes workspace: ${file.path}`);
    equal(digest(await fs.readFile(original)), file.originalSha256, `Original hash ${file.path}`);
    if (files.has(file.path)) equal(file, files.get(file.path), `Conflicting embedded evidence ${file.path}`);
    files.set(file.path, file);
    if (file.path.startsWith('run/')) {
      const target = safeTarget(replay, file.path);
      await fs.mkdir(path.dirname(target), { recursive: true });
      await fs.writeFile(target, restore(file.content));
    }
  }
}
const frozenHashes = prereg.files.map(({ path, originalSha256, normalizedSha256 }) => ({ path, originalSha256, normalizedSha256 }));
equal(packed.frozenPreregistrationFiles, frozenHashes, 'Packed frozen hashes');
equal(published.frozenPreregistrationFiles, frozenHashes, 'Published frozen hashes');
for (const name of ['candidate-freeze.json', 'protocol.json', 'prepare-inputs.mjs', 'validate-inputs.mjs', 'study-runner.mjs', 'analyze-run.mjs', 'publish-results.py', 'verify-publication.mjs']) {
  if (!prereg.files.some(file => file.path === name)) throw new Error(`Missing frozen program/protocol: ${name}`);
}
function readEmbedded(name) {
  const file = files.get(name);
  if (!file) throw new Error(`Missing evidence: ${name}`);
  return JSON.parse(restore(file.content));
}
const freeze = readEmbedded('candidate-freeze.json');
const binding = readEmbedded('publication-binding.json');
const run = readEmbedded('run/run.json');
const completed = readEmbedded('run/completed.json');
const analysis = readEmbedded('analysis.json');
const publicRestored = JSON.parse(restore(JSON.stringify(published)));
equal(published.candidateSourceCommit, freeze.commit, 'Frozen candidate source');
equal(run.candidateSourceAssociation, freeze.commit, 'Run candidate source');
equal(completed.candidateSourceAssociation, freeze.commit, 'Completion candidate source');
equal(run.options.seed, 202610073, 'Frozen run seed');
equal(run.options.setupTimeoutMs, 300000, 'Unchanged setup budget');
equal(run.options.queryTimeoutMs, 60000, 'Frozen query budget');
equal(run.sourceLock.ocbiCommit, freeze.commit, 'Source lock candidate');
equal(published.preregistrationCommit, binding.preregistrationCommit, 'Preregistration commit');
equal(packed.preregistrationCommit, binding.preregistrationCommit, 'Packed preregistration commit');
equal(binding.preregistrationArchiveSha256, digest(preregBytes), 'Actual preregistration binding');
equal(published.seed, 202610073, 'Publication seed');
equal(run.primaryQualityRepeat, 1, 'Primary repeat');
equal(run.options.repeats, 3, 'Pass count');
equal(completed.candidateAndInputLocksUnchanged, true, 'Frozen lock completion');
equal(published.candidateAndInputLocksUnchanged, completed.candidateAndInputLocksUnchanged, 'Published lock completion');
equal(published.startedAt, run.startedAt, 'Start time');
equal(published.completedAt, completed.completedAt, 'Completion time');
equal(publicRestored.postScoreDiagnosis, readEmbedded('post-score-coverage-notes.json'), 'Actual post-score diagnosis');
const conditions = ['ocbi-hybrid', 'ocbi-structural', 'codegraph', 'codebase-memory', 'grepai', 'literal-unindexed', 'plain-file-bm25'];
equal(run.options.conditions, conditions, 'Seven conditions');
const protocol = readEmbedded('protocol.json');
for (const [field, expected] of Object.entries({ seed: 202610073, setupTimeoutMs: 300000, queryTimeoutMs: 60000, repeats: 3, primaryQualityRepeat: 1, conditions })) {
  equal(protocol[field], expected, `Frozen protocol ${field}`);
}
for (const [field, name] of [['protocolSha256', 'protocol.json'], ['sourceLockSha256', 'source-lock.json'], ['interfaceLockSha256', 'tool-interface-lock.json']]) {
  equal(run[field], files.get(name)?.originalSha256, `Run frozen ${name} binding`);
}
if (run.sourceLock.repositories.length !== 9 || new Set(run.sourceLock.repositories.map(repo => repo.name)).size !== 9) throw new Error('Invalid nine-repository declaration');
const load = file => import(pathToFileURL(path.join(project, file)).href);
const { loadCompetitiveRun, buildCompetitiveReport } = await load('scripts/competitive-report.ts');
const { scoreQuery, aggregateScores } = await load('scripts/competitive-scoring.ts');
const { adapterInput, summarizeTracks } = await load('scripts/competitive-benchmark.ts');
const { parseOcbiCitationPaths, parseCodeGraphPaths, parseCodebaseMemoryPaths, parseGrepaiPaths } = await load('scripts/competitive-adapters.ts');
const artifacts = await loadCompetitiveRun(path.join(replay, 'run'));
const rebuilt = buildCompetitiveReport(artifacts.rows, { expectedTasks: artifacts.expectedTasks, conditions, bootstrapSamples: 10000, seed: 202610073 });
equal(rebuilt, published.primaryReport, 'Published primary report and paired intervals');
equal(rebuilt, readEmbedded('run/report.json'), 'Raw primary report');
const totals = { successfulCalls: 0, unsupported: 0, errors: 0 };
const primary = [];
const derivedCells = [];
let records = 0, explicitTasks = 0, naturalTasks = 0;
const source = path.join(replay, 'run/active-source');
function percentile(values, quantile) {
  const sorted = [...values].sort((a, b) => a - b);
  return sorted.length ? sorted[Math.max(0, Math.ceil(quantile * sorted.length) - 1)] : null;
}
for (const repository of run.sourceLock.repositories) {
  const archive = path.join(work, 'archives', `${repository.name}-${repository.revision}.tar`);
  equal(digest(await fs.readFile(archive)), repository.archiveSha256, `Source archive hash ${repository.name}`);
  await fs.rm(source, { recursive: true, force: true });
  await fs.mkdir(source, { recursive: true });
  const extraction = spawnSync('tar', ['-xf', archive, '-C', source], { encoding: 'utf8' });
  if (extraction.status !== 0) throw new Error(`Pinned archive extraction failed: ${extraction.stderr}`);
  const input = readEmbedded(`run/${repository.name}/inputs.json`);
  equal(input.repo, repository, `Repository input ${repository.name}`);
  const frozenDataset = readEmbedded(`datasets/${repository.dataset}`);
  equal(input.dataset, frozenDataset, `Frozen dataset ${repository.name}`);
  const queries = new Map(input.dataset.queries.map(query => [query.id, query]));
  if (queries.size !== input.dataset.queries.length || new Set(input.queryOrder).size !== queries.size) throw new Error(`Duplicate task identity: ${repository.name}`);
  const orderedQueries = input.queryOrder.map(id => {
    if (!queries.has(id)) throw new Error(`Unknown query: ${repository.name}/${id}`);
    return queries.get(id);
  });
  const exact = orderedQueries.filter(query => adapterInput(query).symbol).length;
  const natural = queries.size - exact;
  equal(exact, 6, `Exact-symbol task declaration ${repository.name}`);
  equal(natural, repository.name === 'dry-types' ? 6 : 5, `Natural task declaration ${repository.name}`);
  equal(new Set(orderedQueries.map(query => query.expected.filePath)).size, queries.size, `Distinct primary paths ${repository.name}`);
  explicitTasks += exact;
  naturalTasks += natural;
  const manifest = readEmbedded(`source-manifests/${repository.name}.json`);
  const eligible = new Set(manifest.files.filter(file => file.lexicalEligible).map(file => file.path));
  for (const condition of conditions) {
    const directoryKey = `run/${repository.name}/${condition}`;
    const durations = [], primaryScores = [], perTask = new Map();
    const counts = { successfulCalls: 0, unsupported: 0, errors: 0 };
    for (const repeat of [1, 2, 3]) {
      const prefix = `${directoryKey}/repeat-${repeat}/`;
      equal([...files.keys()].filter(key => key.startsWith(prefix)).length, queries.size, `Pass record count ${prefix}`);
      for (const query of orderedQueries) {
        const key = `${prefix}${query.id}.json`;
        const record = readEmbedded(key);
        equal([record.repeat, record.condition, record.queryId], [repeat, condition, query.id], `Record identity ${key}`);
        equal(record.input, adapterInput(query), `Unchanged query input ${key}`);
        if (!['success', 'error', 'unsupported'].includes(record.score.status)) throw new Error(`Invalid status: ${key}`);
        const unsupported = condition === 'codebase-memory' && !adapterInput(query).symbol;
        equal(record.score.status === 'unsupported', unsupported, `Supported/unsupported declaration ${key}`);
        equal(scoreQuery(query, record.score.rankedPaths, record.score.status), record.score, `Raw score ${key}`);
        if (record.score.status === 'success') {
          let paths;
          if (condition.startsWith('ocbi-')) paths = parseOcbiCitationPaths(record.raw, source, 50);
          else if (condition === 'codegraph') paths = parseCodeGraphPaths(record.raw, source, 50);
          else if (condition === 'codebase-memory') paths = parseCodebaseMemoryPaths(record.raw, source, 50);
          else if (condition === 'grepai') paths = parseGrepaiPaths(record.raw, source, 50);
          else if (condition === 'literal-unindexed') paths = record.raw.stdout.split('\0').filter(Boolean).map(file => file.replace(/^\.\//, '')).filter(file => eligible.has(file)).sort().slice(0, 10);
          else paths = record.raw.candidates.slice(0, 10).map(candidate => candidate.path);
          equal(paths, record.score.rankedPaths, `Successful raw ranking ${key}`);
          counts.successfulCalls++;
          durations.push(record.durationMs);
        } else if (record.score.status === 'unsupported') counts.unsupported++;
        else counts.errors++;
        const previous = perTask.get(query.id) ?? [];
        previous.push({ repeat, status: record.score.status, paths: record.score.rankedPaths, metrics: record.score.metrics ?? null, durationMs: record.durationMs, error: record.error ?? null });
        perTask.set(query.id, previous);
        records++;
        if (repeat === 1) {
          primaryScores.push(record.score);
          primary.push({ repository: repository.name, condition, queryId: query.id, query: query.query, track: record.input.symbol ? 'explicit-symbol' : 'natural-language', expected: query.expected, score: record.score, error: record.error ?? null });
        }
      }
    }
    const summary = readEmbedded(`${directoryKey}/summary.json`);
    const tracks = summarizeTracks(orderedQueries, primaryScores, aggregateScores);
    equal(summary.tracks, tracks, `Derived track metrics ${directoryKey}`);
    const repeatChanges = [...perTask].filter(([, rows]) => rows.some(row => !isDeepStrictEqual({ status: row.status, paths: row.paths }, { status: rows[0].status, paths: rows[0].paths }))).map(([queryId, rows]) => ({ queryId, records: rows })).sort((a, b) => a.queryId.localeCompare(b.queryId));
    const index = readEmbedded(`${directoryKey}/index.json`);
    const setupErrorRecords = Object.hasOwn(index, 'error') ? counts.errors : 0;
    const cell = { repository: repository.name, condition, index, tracks, ...counts, setupErrorRecords, queryErrorRecords: counts.errors - setupErrorRecords, errorAccounting: 'Supported setup/query errors retain zero quality metrics in the supported denominator; unsupported tasks remain separate. Error phase identifies the recorded operation, not an inferred cause.', successfulCallLatencyMs: { p50: percentile(durations, .5), p95: percentile(durations, .95), maximum: percentile(durations, 1) }, repeatChanges, timingLimit: 'Success-only interface timings; setup-error placeholders/unsupported zeros excluded. No cross-interface speed claim.' };
    derivedCells.push(cell);
    for (const field of Object.keys(totals)) totals[field] += counts[field];
  }
}
equal([explicitTasks, naturalTasks, explicitTasks + naturalTasks], [54, 46, 100], '100-task declarations');
equal([artifacts.rows.length, primary.length, records], [700, 700, 2100], 'Complete scored matrix');
equal(totals.unsupported, naturalTasks * 3, 'Declared unsupported passes');
equal(Object.values(totals).reduce((sum, value) => sum + value, 0), records, 'Actual derived pass totals');
equal(published.executionCounts, totals, 'Published execution counts');
function sortOutcomes(rows) {
  return [...rows].sort((a, b) => `${a.repository}/${a.condition}/${a.queryId}`.localeCompare(`${b.repository}/${b.condition}/${b.queryId}`));
}
function sortedCells(cells) {
  return sortOutcomes(cells).map(cell => ({ ...cell, repeatChanges: [...cell.repeatChanges].sort((a, b) => a.queryId.localeCompare(b.queryId)) }));
}
equal(sortOutcomes(publicRestored.taskOutcomes), sortOutcomes(primary), 'Published primary outcomes');
equal(sortOutcomes(analysis.taskOutcomes), sortOutcomes(primary), 'Analyzed primary outcomes');
equal(sortedCells(publicRestored.cells), sortedCells(derivedCells), 'Published derived operational cells');
equal(sortedCells(analysis.results), sortedCells(derivedCells), 'Analyzed derived operational cells');
const primaryByKey = new Map(primary.map(row => [`${row.repository}/${row.condition}/${row.queryId}`, row]));
for (const comparisons of [publicRestored.secondaryComparisons, analysis.secondaryComparisons]) {
  equal(comparisons.length, 6, 'Secondary comparison count');
  const combinations = new Set();
  for (const comparison of comparisons) {
    if (comparison.baseline !== 'ocbi-hybrid' || !['ocbi-structural', 'literal-unindexed', 'plain-file-bm25'].includes(comparison.rival) || !['explicit-symbol', 'natural-language'].includes(comparison.track)) throw new Error('Unknown secondary comparison');
    combinations.add(`${comparison.rival}/${comparison.track}`);
    const leftRows = primary.filter(row => row.condition === comparison.baseline && row.track === comparison.track);
    const pairs = leftRows.map(left => {
      const right = primaryByKey.get(`${left.repository}/${comparison.rival}/${left.queryId}`);
      const delta = left.score.metrics.hitAt5 - right.score.metrics.hitAt5;
      return { repository: left.repository, queryId: left.queryId, baselineStatus: left.score.status, rivalStatus: right.score.status, baselinePaths: left.score.rankedPaths, rivalPaths: right.score.rankedPaths, hitAt5Delta: delta, outcome: delta > 0 ? 'win' : delta < 0 ? 'loss' : 'tie', operationalError: left.score.status === 'error' || right.score.status === 'error' };
    });
    equal(sortOutcomes(comparison.pairs), sortOutcomes(pairs), 'Derived secondary pairs');
    for (const [field, value] of Object.entries({ count: pairs.length, wins: pairs.filter(pair => pair.outcome === 'win').length, losses: pairs.filter(pair => pair.outcome === 'loss').length, ties: pairs.filter(pair => pair.outcome === 'tie').length, operationalErrorPairs: pairs.filter(pair => pair.operationalError).length, exploratory: true, confidenceIntervals: 'Not a preregistered primary interval; descriptive secondary comparison only.' })) equal(comparison[field], value, `Secondary ${field}`);
  }
  equal(combinations.size, 6, 'Distinct secondary comparisons');
}
equal(publicRestored.coverage, analysis.coverage.map(({ representedPathsByKind, ...item }) => ({ ...item, representedFileCountsByKind: Object.fromEntries(Object.entries(representedPathsByKind ?? {}).map(([kind, paths]) => [kind, paths.length])) })), 'Published diagnostic coverage');
const verification = { primaryRows: primary.length, queryPassRecords: records, successfulRawRankingReplays: totals.successfulCalls, reportReproducedExactly: true, reportOriginalSha256: files.get('run/report.json').originalSha256 };
for (const [field, value] of Object.entries(verification)) equal(analysis[field], value, `Analyzed ${field}`);
equal(published.verification, verification, 'Published verification metrics');
equal(completed.primaryRows, primary.length, 'Completion primary count');
equal(published.repositoryConditionCells, derivedCells.length, 'Cell count');
equal(published.primaryQualityRepeat, 1, 'Published primary repeat');

function parseCsv(text) {
  const rows = [];
  let row = [], field = '', quoted = false;
  for (let index = 0; index < text.length; index++) {
    const char = text[index];
    if (char === '"') {
      if (quoted && text[index + 1] === '"') { field += '"'; index++; }
      else quoted = !quoted;
    } else if (!quoted && (char === ',' || char === '\n')) {
      row.push(field); field = '';
      if (char === '\n') { rows.push(row); row = []; }
    } else field += char;
  }
  if (quoted || field || row.length) throw new Error('Incomplete primary CSV');
  return rows;
}
const csvBytes = await fs.readFile(path.join(directory, 'per-task-outcomes.csv'));
equal(published.primaryOutcomesCsv, { path: 'per-task-outcomes.csv', sha256: digest(csvBytes), rows: primary.length, unsupportedMetrics: 'blank' }, 'Primary CSV binding');
const [headers, ...csvRows] = parseCsv(restore(csvBytes.toString('utf8')));
equal(headers, ['repository', 'condition', 'queryId', 'track', 'query', 'status', 'hitAt1', 'hitAt5', 'mrrAt10', 'ndcgAt10', 'rankedPaths', 'expected', 'error'], 'CSV columns');
equal(csvRows.length, 700, 'CSV primary row count');
const csvKeys = new Set();
for (const values of csvRows) {
  equal(values.length, headers.length, 'CSV field count');
  const row = Object.fromEntries(headers.map((header, index) => [header, values[index]]));
  const key = `${row.repository}/${row.condition}/${row.queryId}`;
  if (csvKeys.has(key) || !primaryByKey.has(key)) throw new Error(`Unexpected CSV row: ${key}`);
  csvKeys.add(key);
  const original = primaryByKey.get(key);
  for (const field of ['repository', 'condition', 'queryId', 'track', 'query']) equal(row[field], original[field], `CSV ${field}`);
  equal(row.status, original.score.status, 'CSV status');
  equal(JSON.parse(row.rankedPaths), original.score.rankedPaths, 'CSV rankings');
  equal(JSON.parse(row.expected), original.expected, 'CSV gold');
  equal(row.error, original.error ?? '', 'CSV error');
  for (const field of ['hitAt1', 'hitAt5', 'mrrAt10', 'ndcgAt10']) {
    if (original.score.status === 'unsupported') equal(row[field], '', `Unsupported CSV ${field}`);
    else {
      if (!row[field]) throw new Error(`Missing supported CSV metric: ${key}/${field}`);
      equal(Number(row[field]), original.score.metrics[field], `CSV ${field}`);
    }
  }
}
const observation = {
  schemaVersion: 1, kind: 'published-normalized-evidence-replay', independentReview: false,
  pinnedSourceArchivesRequiredForRawPathValidation: true, nativeIndexesRequiredForThisReplay: false, scoredRetrievalRequestsIssued: 0,
  candidateSourceCommit: freeze.commit, seed: 202610073,
  preregistrationArchiveSha256: digest(preregBytes), resultsEvidenceSha256: digest(packedBytes), reportSha256: digest(reportBytes), primaryOutcomesCsvSha256: digest(csvBytes),
  embeddedHashesVerified: prereg.files.length + packed.files.length, embeddedOriginalHashesVerified: prereg.files.length + packed.files.length, frozenPreregistrationOriginalHashesVerified: prereg.files.length,
  tasks: { total: explicitTasks + naturalTasks, explicitSymbol: explicitTasks, naturalLanguage: naturalTasks }, passes: 3,
  primaryRows: primary.length, queryPassRecords: records, successfulRawPathReplays: totals.successfulCalls, unsupportedPassRecords: totals.unsupported, errorPassRecords: totals.errors,
  primaryReportReproducedExactly: true, operationalCellsAndRepeatChangesReproducedExactly: true, primaryCsvReproducedExactly: true,
  script: { originalSha256: digest(await fs.readFile(path.join(work, 'verify-publication.mjs'))), content: await fs.readFile(path.join(work, 'verify-publication.mjs'), 'utf8') },
  interpretation: 'Replays normalized published execution evidence and rebuilds scoring/paired intervals using immutable frozen helpers. Actual failures, unsupported declarations and repeat changes are retained and checked. Raw-path containment uses hash-verified pinned source archives. Does not independently rerun participant tools or establish representative, blind or SOTA claims.',
};
await fs.writeFile(path.join(directory, 'verification.json'), JSON.stringify(observation, null, 2) + '\n', { flag: 'wx' });
await fs.rm(replay, { recursive: true, force: true });
console.log(JSON.stringify({ ...observation, script: { originalSha256: observation.script.originalSha256 } }, null, 2));
